			{ new CultureInfo("fa-IR"), "این گزینه با هر Tobii بازی ردیاب چشم (4C، EyeX ها، Alienware، استیل، و غیره) کار خواهد کرد" },
			{ new CultureInfo("pl-PL"), "Opcja ta będzie współpracować z dowolnym Tobii Gaming eye tracker (4c, EyeX, Alienware, Steelseries, etc)" },
