			{ new CultureInfo("sl-SI"), "Ta možnost bo delo s katero koli Tobii Gaming oči tracker (4C, EyeX, Alienware, SteelSeries, itd)" },
			{ new CultureInfo("sk-SK"), "Táto voľba bude fungovať s akýmkoľvek Tobi Gaming očí tracker (4C, EyeX, Alienware, SteelSeries, etc)" },
			{ new CultureInfo("es-ES"), "Esta opción funciona con cualquier rastreador ocular de Tobii juego (4C, EyeX, Alienware, Steelseries, etc)" },
