		public static Dictionary<CultureInfo, string> TOBII_ASSISTIVE_INFO = new Dictionary<CultureInfo, string>()
		{
			{ new CultureInfo("ca-ES"), "Per utilitzar Optikey amb un rastrejador ocular d'assistència, ja sigui que necessita la nova versió de Tobii Windows Control, o el motor de Tobii Eye Tracking. Si cal utilitzar la versió antiga de l'aplicació Tobii Windows Control (Tobii Gaze Interaction Software), aleshores us farà falta per controlar Optikey utilitzant la posició del ratolí en lloc. " },
			{ new CultureInfo("zh-CN"), "若要搭配辅助眼动仪来使用 Optikey，您需要安装新版的 Windows Control 或 Tobii Eye Tracking 引擎。若您需要使用旧版的 Tobii Windows Control 程序（包含 Tobii Gaze Interaction 设置），您需要改用鼠标位置控制 Optikey。" },
			{ new CultureInfo("zh-TW"), "若要搭配輔助眼動儀來使用 Optikey，您需要安裝新版的 Windows Control 或 Tobii Eye Tracking 引擎。若您需要使用舊版的 Tobii Windows Control 程式 (包含 Tobii Gaze Interaction 設定)，您需要改用滑鼠位置控制 Optikey。" },
			{ new CultureInfo("hr-HR"), "Za korištenje Optikey s pomoćnim oka Tracker Tobii, bilo je potrebno novu verziju Tobii Windows Control, odnosno motor Tobii očiju praćenje. Ako trebate koristiti staru verziju upravljačkog primjene Tobii Windows Control (Tobii Gaze Interaction Software), onda ćete morati kontrolirati Optikey pomoću položaja miša umjesto." },
			{ new CultureInfo("cs-CZ"), "Chcete-li používat Optikey s asistenční očí tracker, musíte buď novou verzi systému Windows Control, nebo motoru Tobii Eye Tracking. Pokud potřebujete použít starou verzi ovládacího aplikace Tobii Windows Control (Tobii Gaze Interaction Software), pak se budete muset řídit Optikey pomocí pozici myši místo. Pro více informací viz www.optikey.org/help" },
			{ new CultureInfo("da-DK"), "For at bruge Optikey med et hjælpemiddel øje tracker, du enten har brug for den nye version af Windows Control eller Tobii Eye Tracking motor. Hvis du skal bruge den gamle version af Tobii Windows Control ansøgning (Tobii Gaze Interaction Software), så bliver du nødt til at kontrollere Optikey ved hjælp af musen position i stedet. " },
			{ new CultureInfo("nl-BE"), "Om gebruik te maken Optikey met een ondersteunende eye tracker, moet u ofwel de nieuwe versie van Tobii Windows Control, of de Tobii Eye Tracking motor nodig. Als u de oude versie van de Tobii Windows Control toepassing (Tobii Gaze Interaction Software) gebruikt, dan zul je nodig hebt om te controleren Optikey met de muis positie plaats. " },
			{ new CultureInfo("nl-NL"), "Om gebruik te maken Optikey met een ondersteunende eye tracker, moet u ofwel de nieuwe versie van Tobii Windows Control, of de Tobii Eye Tracking motor nodig. Als u de oude versie van de Tobii Windows Control toepassing (Tobii Gaze Interaction Software) gebruikt, dan zul je nodig hebt om te controleren Optikey met de muis positie plaats. " },
			{ new CultureInfo("en-CA"), "To use Optikey with an assistive eye tracker, you either need the new version of Windows Control, or the Tobii Eye Tracking engine. If you need to use the old version of the Tobii Windows control application (including Tobii Gaze Interaction settings), then you will need to control Optikey using mouse position instead." },
			{ new CultureInfo("en-GB"), "To use Optikey with an assistive eye tracker, you either need the new version of Windows Control, or the Tobii Eye Tracking engine. If you need to use the old version of the Tobii Windows control application (including Tobii Gaze Interaction settings), then you will need to control Optikey using mouse position instead." },
			{ new CultureInfo("en-US"), "To use Optikey with an assistive eye tracker, you either need the new version of Windows Control, or the Tobii Eye Tracking engine. If you need to use the old version of the Tobii Windows control application (including Tobii Gaze Interaction settings), then you will need to control Optikey using mouse position instead." },
			{ new CultureInfo("fi-FI"), "Käyttää Optikey kanssa avustavien silmänseurain, sinun täytyy joko uuden Tobii Windows Control tai Tobii Eye Tracking moottori. Jos joudut käyttämään vanhaa versiota Tobii Windows Control (Tobii Gaze Interaction Software), sinun täytyy valvoa Optikey hiirellä asentoon sijasta. " },
			{ new CultureInfo("fr-CA"), "Pour utiliser Optikey avec un oculomètre d'assistance, vous devez soit la nouvelle version de Tobii Windows Control, ou le moteur de suivi Tobii Eye. Si vous avez besoin d'utiliser l'ancienne version de Tobii Windows Control (Tobii Gaze Interaction), alors vous devrez contrôler Optikey utilisant la position de la souris à la place. " },
			{ new CultureInfo("fr-FR"), "Pour utiliser Optikey avec un oculomètre d'assistance, vous devez soit la nouvelle version de Tobii Windows Control, ou le moteur de suivi Tobii Eye. Si vous avez besoin d'utiliser l'ancienne version de Tobii Windows Control (Tobii Gaze Interaction), alors vous devrez contrôler Optikey utilisant la position de la souris à la place. " },
			{ new CultureInfo("ka-GE"), "იმისათვის, რომ გამოიყენოთ Optikey ერთად Tobii დამხმარე თვალის tracker, თქვენ არც უნდა ახალი ვერსია Windows Control, ან Tobii Eye Tracking სისტემა. თუ თქვენ უნდა გამოვიყენოთ ძველი ვერსია Tobii Windows კონტროლის პროგრამა (Tobii Gaze Interaction Software), მაშინ თქვენ უნდა აკონტროლოთ Optikey მაუსის პოზიცია ნაცვლად. " },
			{ new CultureInfo("de-DE"), "Um Optikey mit einem Unterstützungs-Eye-Tracker zu benutzen, brauchen Sie entweder eine neue Version von Windows Control, oder die Tobii Eye Tracking Software. Wenn Sie die alte Version der Tobii Windows Control Software benutzen müssen (einschließlich die Tobii Gaze Interaction Einstellungen), dann müssen Sie Optikey über die Mausposition steuern." },
			{ new CultureInfo("el-GR"), "Για να χρησιμοποιήσετε Optikey με βοηθητικές tracker μάτι, θα πρέπει είτε τη νέα έκδοση των Windows Control, ή τον κινητήρα Tobii Eye Tracking. Εάν πρέπει να χρησιμοποιήσετε την παλιά έκδοση της εφαρμογής ελέγχου Tobii Windows Control (Tobii Gaze Interaction Software), τότε θα πρέπει να ελέγχει Optikey χρησιμοποιώντας τη θέση του ποντικιού αντ 'αυτού. " },
			{ new CultureInfo("he-IL"), "כדי להשתמש Optikey עם גשש Tobii העין ,שאתה צריך את הגרסה החדשה של הבקרה של Tobii Windows Control, או מנוע עקיבת העין Tobii" },
			{ new CultureInfo("hi-IN"), "एक सहायक आई ट्रैकर के साथ Optikey का उपयोग करने के लिए, आपको या तो विंडोज कंट्रोल के नए संस्करण की आवश्यकता है, या टोबि आई ट्रैकिंग इंजन। अगर आपको Tobii विंडोज कंट्रोल एप्लिकेशन (Tobii Gaze इंटरैक्शन सेटिंग्स सहित) के पुराने संस्करण का उपयोग करने की आवश्यकता है, तो आपको माउस की स्थिति का उपयोग करके Optikey को नियंत्रित करने की आवश्यकता होगी।" },
			{ new CultureInfo("hu-HU"), "Ahhoz, hogy használni Optikey egy segítő szemkövetővel, akkor sem kell az új verzió a Windows Control vagy a Tobii Eye Tracking motort. Ha kell használni a régi verziót a Tobii Windows-vezérlési alkalmazás (beleértve Tobii Gaze Interaction beállítások), akkor meg kell, hogy ellenőrizzék optikey egér segítségével összesen helyett." },
			{ new CultureInfo("it-IT"), "Per usare Optikey con un dispositivo di tracciamento oculare, hai bisogno o della nuova versione di Windows Control, oppure del software Tobii Eye Tracking. Se hai la vecchia versione del software di controllo Tobii per Windows (incluse le impostazioni Tobii Gaze Interaction), allora per usare Optikey devi impostarne il controllo via posizione del mouse." },
			{ new CultureInfo("ja-JP"), "支援アイトラッカーでOptikey使用するには、次のいずれかは、Windows Control、または Tobii アイトラッキングエンジンの新しいバージョンが必要です。あなたは（Tobii Gaze Interaction Software）、Tobii Windows Control アプリケーションの古いバージョンを使用する必要がある場合は、代わりにマウスの位置を使用してOptikey制御する必要があります。" },
			{ new CultureInfo("ko-KR"), "Tobii 보조 안구 추적기와 Optikey 사용하려면,  Tobii Windows Control  윈도우 제어, 또는 Tobii 눈 추적 엔진의 새 버전이 필요합니다. 당신이 (Tobii Gaze Interaction Software) Tobii 윈도우 제어 응용 프로그램의 이전 버전을 사용해야하는 경우, 당신은 대신 마우스 위치를 사용하여 Optikey 제어해야합니다. " },
			{ new CultureInfo("fa-IR"), "ببه منظور استفاده از این نرم افزار Optikey با ردیاب چشم Tobii، شما هم نیاز به نسخه جدید Tobii Windows Control و یا موتور Tobii ردیابی چشم. اگر شما نیاز به استفاده از نسخه های قدیمی نرم Tobii Windows Control (Tobii Gaze Interaction System)، سپس شما نیاز به کنترل Optikey با استفاده از موقعیت ماوس به جای. " },
			{ new CultureInfo("pl-PL"), "Aby korzystać Optikey z Tobii wspomagających eye tracker, albo trzeba nową wersję Tobii Windows Control lub silnika Tobii Eye Tracking. Jeśli musisz używać starej wersji aplikacji Tobii Windows Control (Tobii Gaze Interaction Software), a następnie trzeba będzie kontrolować Optikey użyciu pozycji myszy zamiast. " },
			{ new CultureInfo("pt-PT"), "Para usar Optikey um gerenciador de visão assistiva, você nem precisa a nova versão do Tobii Windows Control, ou o motor Eye Tracking Tobii. Se você precisa usar a versão antiga do aplicativo de Tobii Windows Control (Tobii Gaze Interaction Software), então você vai precisar para controlar Optikey usando posição do mouse em seu lugar. Para mais informações, consulte www.optikey.org/help" },
			{ new CultureInfo("ru-RU"), "Для того, чтобы использовать Optikey с Tobii  реабилитационным трекером глаз, вам необходимо либо новую версия Tobii Windows Control или двигатель Tobii отслеживания глаз. Если вам нужно использовать старую версию приложения Tobii Windows Control  (Tobii Gaze Interaction Software), то вам нужно будет контролировать Optikey используя положение мыши вместо этого. " },
			{ new CultureInfo("sr-Cyrl-RS"), "Да бисте користили Optikey са помоћним очију трагач, ти или треба нову верзију Tobii Windows Control , или софтвер Tobii Eye Tracking. Ако морате да користите стару верзију  Tobii Windows  Control (Tobii Gaze Interaction Software), онда ћете морати да контролишете Optikey користећи позицију миша уместо тога. " },
			{ new CultureInfo("sl-SI"), "Za uporabo Optikey s pomožno oči tracker, ali boste potrebovali novo različico nadzor Tobii Windows Control, ali motor Tobii sledenje oči. Če želite uporabljati staro različico aplikacije za nadzor Tobii Windows Control (Tobii Gaze Interaction Software), potem boste morali za nadzor Optikey namesto uporabe položaj miške." },
			{ new CultureInfo("sk-SK"), "Ak chcete používať Optikey s asistenčnou očí tracker, musíte buď novú verziu systému Windows Control, alebo motora Tobi Eye Tracking. Ak potrebujete použiť starú verziu ovládacieho programu Tobi Windows (vrátane nastavenia Tobi Gaze interakcie), potom sa budete musieť riadiť Optikey pomocou pozíciu myši miesto. " },
			{ new CultureInfo("es-ES"), "Para utilizar Optikey con un rastreador ocular de asistencia, ya sea que necesita la nueva versión de Tobii Windows Control, o el motor de Tobii Eye Tracking. Si es necesario utilizar la versión antigua de la aplicación Tobii Windows Control (Tobii Gaze Interaction Software), entonces necesitará para controlar Optikey utilizando la posición del ratón en lugar. " },
			{ new CultureInfo("tr-TR"), "Optikey'i bir göz takip cihazı ile kullanmak için ya Windows Control'ün yeni sürümüne ya da Tobii Eye Tracking engine  ihtiyacınız var. Tobii Windows kontrol uygulamasının eski sürümünü kullanmanız gerekiyorsa (Tobii Gaze Etkileşim ayarları dahil), bunun yerine Optikey'i fare konumunu kullanarak kontrol etmeniz gerekecektir." },
			{ new CultureInfo("uk-UA"), "Для того, щоб використовувати Optikey з Tobii реабілітаційним трекером очей, вам необхідно або нову версія Tobii Windows Control  або двигун Tobii відстеження очей. Якщо вам потрібно використовувати стару версію програми Tobii Windows Control  (Tobii Gaze Interaction Software), то вам потрібно буде контролювати Optikey використовуючи положення миші замість цього. " },
			{ new CultureInfo("ur-PK"), "ایک معاون آنکھ ٹریکر کے ساتھ Optikey کو استعمال کرنے کے لئے، آپ کو یا تو Tobii Windows Control کے کنٹرول، یا Tobii آنکھ سے باخبر رکھنے کے انجن کا نیا ورژن کی ضرورت ہے. آپ Tobii ونڈوز کے Tobii Windows Control کی درخواست (Tobii Gaze Interaction Software) کے پرانے ورژن استعمال کرنے کے لئے کی ضرورت ہے تو، پھر آپ کو اس کی بجائے ماؤس پوزیشن کو استعمال کرتے ہوئے Optikey کو کنٹرول " },
		};
		public static Dictionary<CultureInfo, string> OTHER_TRACKER = new Dictionary<CultureInfo, string>()
		{
			{ new CultureInfo("ca-ES"), " Si el vostre rastrejador d’ulls no apareix aquí o necessiteu una versió de 32 bits d’Optikey, feu clic a l’enllaç següent per obtenir més informació.\r\nSi voleu continuar amb la instal·lació, Optikey estarà controlada per la posició del ratolí. Això li permet treballar amb entrades alternatives com un ratolí de capçal o qualsevol rastrejador d’ulls que permeti controlar la posició del ratolí amb els ulls." },
			{ new CultureInfo("zh-CN"), "If your eye tracker is not listed here, or you require a 32 bit version of Optikey, please click the link below for more information. \r\n\r\nIf you want to continue with installation, Optikey will be controlled by your mouse position. This allows it to work with alternative inputs such as a head mouse, or any eye tracker that allows you to control the mouse position with your eyes." },
			{ new CultureInfo("zh-TW"), "如果您的眼動追蹤器未在此列出，或您需要 Optikey 的 32 位版本，請點擊下方連結以獲取更多資訊。" },
			{ new CultureInfo("hr-HR"), " Ako vam tracker za oči nije naveden ovdje ili vam je potrebna 32 -bitna verzija Optikey, kliknite donju vezu za više informacija.\r\nAko želite nastaviti s instalacijom, Optikey će kontrolirati položaj vašeg miša. To mu omogućava da radi s alternativnim ulazima kao što je miš za glavu ili bilo kojim praćenjem očiju koji vam omogućuje kontrolu položaja miša očima." },
			{ new CultureInfo("cs-CZ"), " Pokud váš oční sledovač není zde uveden nebo potřebujete 32bitovou verzi Optikey, pro více informací klikněte na odkaz níže.\r\nPokud chcete pokračovat v instalaci, bude Optikey ovládána pozicí myši. To mu umožňuje pracovat s alternativními vstupy, jako je hlava myši, nebo jakýmkoli sledovačem očí, které vám umožní ovládat polohu myši očima." },
			{ new CultureInfo("da-DK"), " Hvis din Eye Tracker ikke er anført her, eller du har brug for en 32 bit version af Optikey, skal du klikke på linket herunder for mere information.\r\nHvis du vil fortsætte med installationen, kontrolleres Optikey af din museposition. Dette giver det mulighed for at arbejde med alternative input såsom en hovedmus eller enhver øjenspor, der giver dig mulighed for at kontrollere musepositionen med dine øjne." },
			{ new CultureInfo("nl-BE"), " Als uw eye tracker hier niet wordt vermeld of u een 32 -bits versie van Optikey nodig heeft, klikt u op de onderstaande link voor meer informatie.\r\n     Als u wilt doorgaan met installatie, wordt Optikey bestuurd door uw muispositie. Hierdoor kan het werken met alternatieve ingangen zoals een hoofdmuis of een eye -tracker waarmee u de muispositie met uw ogen kunt regelen." },
			{ new CultureInfo("nl-NL"), " Als uw eye tracker hier niet wordt vermeld of u een 32 -bits versie van Optikey nodig heeft, klikt u op de onderstaande link voor meer informatie.\r\n     Als u wilt doorgaan met installatie, wordt Optikey bestuurd door uw muispositie. Hierdoor kan het werken met alternatieve ingangen zoals een hoofdmuis of een eye -tracker waarmee u de muispositie met uw ogen kunt regelen." },
			{ new CultureInfo("en-CA"), "If your eye tracker is not listed here, or you require a 32 bit version of Optikey, please click the link below for more information. \r\n\r\nIf you want to continue with installation, Optikey will be controlled by your mouse position. This allows it to work with alternative inputs such as a head mouse, or any eye tracker that allows you to control the mouse position with your eyes." },
			{ new CultureInfo("en-GB"), "If your eye tracker is not listed here, or you require a 32 bit version of Optikey, please click the link below for more information. \r\n\r\nIf you want to continue with installation, Optikey will be controlled by your mouse position. This allows it to work with alternative inputs such as a head mouse, or any eye tracker that allows you to control the mouse position with your eyes." },
			{ new CultureInfo("en-US"), "If your eye tracker is not listed here, or you require a 32 bit version of Optikey, please click the link below for more information. \r\n\r\nIf you want to continue with installation, Optikey will be controlled by your mouse position. This allows it to work with alternative inputs such as a head mouse, or any eye tracker that allows you to control the mouse position with your eyes." },
			{ new CultureInfo("fi-FI"), " Jos silmäseurantasi ei ole tässä lueteltu tai tarvitset 32 ​​-bittin version Optikeyistä, napsauta alla olevaa linkkiä saadaksesi lisätietoja.\r\nJos haluat jatkaa asennuksen kanssa, Optikey ohjataan hiiren sijainnissasi. Tämän avulla se voi toimia vaihtoehtoisilla tuloilla, kuten päähiirellä, tai millä tahansa silmäseurantalaitteella, jonka avulla voit hallita hiiren sijaintia silmilläsi." },
			{ new CultureInfo("fr-CA"), " Si votre tracker pour les yeux n'est pas répertorié ici, ou si vous avez besoin d'une version 32 bits d'Optikey, veuillez cliquer sur le lien ci-dessous pour plus d'informations.\r\n     Si vous souhaitez continuer avec l'installation, Optikey sera contrôlé par la position de votre souris. Cela lui permet de fonctionner avec des entrées alternatives telles qu'une souris de tête ou tout tracker pour les yeux qui vous permet de contrôler la position de la souris avec vos yeux." },
			{ new CultureInfo("fr-FR"), " Si votre tracker pour les yeux n'est pas répertorié ici, ou si vous avez besoin d'une version 32 bits d'Optikey, veuillez cliquer sur le lien ci-dessous pour plus d'informations.\r\n     Si vous souhaitez continuer avec l'installation, Optikey sera contrôlé par la position de votre souris. Cela lui permet de fonctionner avec des entrées alternatives telles qu'une souris de tête ou tout tracker pour les yeux qui vous permet de contrôler la position de la souris avec vos yeux." },
			{ new CultureInfo("ka-GE"), " თუ თქვენი თვალის ტრეკერი აქ არ არის ჩამოთვლილი, ან გჭირდებათ Optikey- ის 32 ბიტიანი ვერსია, გთხოვთ, დააჭირეთ ქვემოთ მოცემულ ბმულს დამატებითი ინფორმაციისთვის.\r\nთუ გსურთ ინსტალაციის გაგრძელება, Optikey კონტროლდება მაუსის პოზიციით. ეს საშუალებას აძლევს მას იმუშაოს ალტერნატიულ საშუალებებთან, როგორიცაა თაგვი, ან ნებისმიერი თვალის ტრეკერი, რომელიც საშუალებას გაძლევთ აკონტროლოთ თაგვის პოზიცია თვალებით." },
			{ new CultureInfo("de-DE"), " Wenn Ihr Eye Tracker hier nicht aufgeführt ist oder Sie eine 32 -Bit -Version von Optikey benötigen, klicken Sie bitte auf den Link unten, um weitere Informationen zu erhalten.\r\nWenn Sie die Installation fortsetzen möchten, wird Optikey von Ihrer Mausposition gesteuert. Auf diese Weise können Sie mit alternativen Eingaben wie einer Kopfmaus oder einem Augenverfolger arbeiten, mit dem Sie die Mausposition mit Ihren Augen steuern können." },
			{ new CultureInfo("el-GR"), " Εάν ο παρατηρητής ματιών σας δεν αναφέρεται εδώ ή χρειάζεστε μια έκδοση 32 bit του Optikey, κάντε κλικ στον παρακάτω σύνδεσμο για περισσότερες πληροφορίες.\r\nΕάν θέλετε να συνεχίσετε με την εγκατάσταση, το Optikey θα ελέγχεται από τη θέση του ποντικιού σας. Αυτό του επιτρέπει να λειτουργεί με εναλλακτικές εισόδους, όπως ποντίκι κεφαλής ή οποιοδήποτε ιχνηλάτη που σας επιτρέπει να ελέγχετε τη θέση του ποντικιού με τα μάτια σας." },
			{ new CultureInfo("he-IL"), " אם גשש העיניים שלך אינו מופיע כאן, או שאתה זקוק לגרסת 32 סיביות של Optikey, אנא לחץ על הקישור למטה למידע נוסף.\r\n     אם אתה רוצה להמשיך בהתקנה, Optikey ישלט על ידי מיקום העכבר שלך. זה מאפשר לו לעבוד עם תשומות אלטרנטיביות כמו עכבר ראש, או כל גשש עיניים המאפשר לך לשלוט על מיקום העכבר בעיניים." },
			{ new CultureInfo("hi-IN"), "If your eye tracker is not listed here, or you require a 32 bit version of Optikey, please click the link below for more information. \r\n\r\nIf you want to continue with installation, Optikey will be controlled by your mouse position. This allows it to work with alternative inputs such as a head mouse, or any eye tracker that allows you to control the mouse position with your eyes." },
			{ new CultureInfo("hu-HU"), " Ha a szemkövető nem szerepel itt, vagy szüksége van egy 32 bites verzióra az Optikey -ről, kérjük, kattintson az alábbi linkre.\r\nHa folytatni szeretné a telepítést, az Optikey -t az egér pozíciója irányítja. Ez lehetővé teszi, hogy alternatív bemenetekkel, például fej egérrel vagy bármilyen szemkövetővel működjön, amely lehetővé teszi az egér helyzetének a szemével történő irányítását." },
			{ new CultureInfo("it-IT"), " Se il tuo eye tracker non è elencato qui o hai bisogno di una versione di Optikey a 32 bit, fai clic sul link in basso per ulteriori informazioni.\r\nSe vuoi continuare con l'installazione, Optikey sarà controllato dalla posizione del mouse. Ciò gli consente di funzionare con input alternativi come un topo per la testa o qualsiasi tracker oculare che ti consente di controllare la posizione del mouse con gli occhi." },
			{ new CultureInfo("ja-JP"), " アイトラッカーがここにリストされていない場合、または32ビットバージョンのOptikeyが必要な場合は、詳細については以下のリンクをクリックしてください。\r\nインストールを続けたい場合は、Optikeyがマウスの位置によって制御されます。これにより、ヘッドマウスなどの代替入力、または目でマウスの位置を制御できるアイトラッカーで動作できます。" },
			{ new CultureInfo("ko-KR"), " 눈 추적기가 여기에 나열되지 않았거나 32 비트 버전의 Optikey가 필요한 경우 아래 링크를 클릭하여 자세한 내용을보십시오.\r\n설치를 계속하려면 Optikey는 마우스 위치에 따라 제어됩니다. 이를 통해 헤드 마우스와 같은 대체 입력 또는 눈으로 마우스 위치를 제어 할 수있는 아이 트래커와 함께 작동 할 수 있습니다." },
			{ new CultureInfo("fa-IR"), " اگر ردیاب چشم شما در اینجا ذکر نشده است ، یا به نسخه 32 بیتی Optikey نیاز دارید ، لطفاً برای اطلاعات بیشتر روی پیوند زیر کلیک کنید.\r\nاگر می خواهید با نصب ادامه دهید ، Optikey توسط موقعیت موش شما کنترل می شود. این اجازه می دهد تا با ورودی های جایگزین مانند ماوس سر یا هر ردیاب چشم که به شما امکان می دهد موقعیت ماوس را با چشم خود کنترل کنید ، کار کند." },
			{ new CultureInfo("pl-PL"), " Jeśli śledzenie wzroku nie jest tutaj wymienione lub potrzebujesz 32 -bitowej wersji Optikey, kliknij poniższy link, aby uzyskać więcej informacji.\r\nJeśli chcesz kontynuować instalację, Optikey będzie kontrolowany przez twoją pozycję myszy. Pozwala to na działanie z alternatywnymi wejściami, takimi jak mysz głowica lub dowolny śledzenie wzroku, który pozwala kontrolować pozycję myszy oczami." },
			{ new CultureInfo("pt-PT"), " Se o seu rastreador ocular não estiver listado aqui ou você precisar de uma versão de 32 bits do Optikey, clique no link abaixo para obter mais informações.\r\nSe você deseja continuar com a instalação, o Optikey será controlado pela posição do seu mouse. Isso permite que ele funcione com entradas alternativas, como um mouse da cabeça ou qualquer rastreador ocular que permita controlar a posição do mouse com os olhos." },
			{ new CultureInfo("ru-RU"), " Если ваш трекер глаз здесь не указан, или вам требуется 32 -битная версия Optikey, пожалуйста, нажмите на ссылку ниже для получения дополнительной информации.\r\nЕсли вы хотите продолжить установку, Optikey будет контролироваться положением вашей мыши. Это позволяет ему работать с альтернативными входами, такими как головная мышь, или любые глазные трекер, который позволяет вам управлять положением мыши своими глазами." },
			{ new CultureInfo("sr-Cyrl-RS"), " Ако ваш трагач за очи овде није наведено, или вам је потребна 32-битна верзија оптикеи, молимо да кликнете на доњу везу за више информација.\r\nАко желите да наставите са инсталацијом, оптикеи ће бити под контролом вашег положаја миша. То омогућава да ради са алтернативним улазима као што су главна миш, или било који очни трацкер који вам омогућава да контролишете положај миша са очима." },
			{ new CultureInfo("sl-SI"), " Če vaš sledilnik oči ni naveden tukaj ali potrebujete 32 -bitno različico Optikeyja, za več informacij kliknite spodnjo povezavo.\r\nČe želite nadaljevati z namestitvijo, bo Optikey nadzoroval položaj miške. To mu omogoča, da deluje z alternativnimi vhodi, kot je miška glave ali kateri koli sledilnik oči, ki vam omogoča nadzor nad položajem miške z očmi." },
			{ new CultureInfo("sk-SK"), " Ak tu nie je uvedený váš sledovač očí alebo potrebujete 32 -bitovú verziu Optikey, kliknite na odkaz nižšie, kde nájdete ďalšie informácie.\r\nAk chcete pokračovať v inštalácii, optikey bude ovládaný polohou myši. To mu umožňuje pracovať s alternatívnymi vstupmi, ako je hlava myši alebo akýkoľvek sledovač očí, ktorý vám umožňuje ovládať polohu myši vašimi očami." },
			{ new CultureInfo("es-ES"), " Si su rastreador ocular no está en la lista aquí, o necesita una versión de 32 bits de OptikeY, haga clic en el enlace a continuación para obtener más información.\r\nSi desea continuar con la instalación, OptikeY será controlado por la posición de su mouse. Esto le permite funcionar con entradas alternativas como un mouse de cabeza o cualquier rastreador ocular que le permita controlar la posición del mouse con los ojos." },
			{ new CultureInfo("tr-TR"), "If your eye tracker is not listed here, or you require a 32 bit version of Optikey, please click the link below for more information. \r\n\r\nIf you want to continue with installation, Optikey will be controlled by your mouse position. This allows it to work with alternative inputs such as a head mouse, or any eye tracker that allows you to control the mouse position with your eyes." },
			{ new CultureInfo("uk-UA"), " Якщо ваш трекер очей тут не вказаний, або вам потрібна 32 -бітна версія Optikey, натисніть посилання нижче для отримання додаткової інформації.\r\nЯкщо ви хочете продовжувати встановлення, Optikey буде контролюватися вашою мишкою. Це дозволяє йому працювати з альтернативними входами, такими як головна миша, або будь -який трекер очей, який дозволяє керувати положенням миші очима." },
			{ new CultureInfo("ur-PK"), " اگر آپ کے آئی ٹریکر کو یہاں درج نہیں کیا گیا ہے ، یا آپ کو اوپٹکی کے 32 بٹ ورژن کی ضرورت ہے تو ، مزید معلومات کے لئے نیچے دیئے گئے لنک پر کلک کریں۔\r\nاگر آپ تنصیب کے ساتھ جاری رکھنا چاہتے ہیں تو ، آپٹکی کو آپ کے ماؤس کی پوزیشن کے ذریعہ کنٹرول کیا جائے گا۔ اس سے یہ متبادل آدانوں جیسے ہیڈ ماؤس ، یا کوئی آئی ٹریکر کے ساتھ کام کرنے کی اجازت دیتا ہے جو آپ کو اپنی آنکھوں سے ماؤس کی پوزیشن پر قابو پانے کی اجازت دیتا ہے۔" },
		};
	}
}
